<?php
require_once __DIR__ . '/../database/config.php';
require_once __DIR__.'/../database/config.php';require_once __DIR__.'/../process/accessControlHelpers.php';require_once __DIR__.'/../common/systemDataHelpers.php';
$pdo=getDB();requirePageAccess($pdo,'notifications');
if(!function_exists('e')){function e($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}}
$items=sys_notification_items($pdo);$unread=array_filter($items,fn($i)=>empty($i['is_read']));$flash=$_SESSION['notification_flash']??'';unset($_SESSION['notification_flash']);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications - <?= htmlspecialchars(app_name(), ENT_QUOTES, 'UTF-8') ?></title><link rel="stylesheet" href="../common/fonts.css"><style>*{box-sizing:border-box}body{margin:0;background:#f8f9fb;color:#111827;font-family:Sora,sans-serif}.page{max-width:1000px;margin:auto;padding:32px}.head{display:flex;justify-content:space-between;align-items:end;gap:14px;flex-wrap:wrap;margin-bottom:22px}h1{margin:0;font-size:1.55rem}.sub{color:#6b7280;font-size:.84rem;margin-top:5px}.btn{border:0;background:#111827;color:#fff;border-radius:8px;padding:10px 14px;font-weight:700;cursor:pointer}.flash{background:#ecfdf5;color:#047857;border:1px solid #a7f3d0;border-radius:10px;padding:12px;margin-bottom:15px}.list{display:grid;gap:10px}.item{display:grid;grid-template-columns:12px 1fr auto;gap:13px;background:#fff;border:1px solid #e5e7eb;border-radius:13px;padding:16px;align-items:start}.item.read{opacity:.68}.dot{width:10px;height:10px;border-radius:50%;margin-top:6px;background:#2563eb}.dot.warning{background:#d97706}.dot.danger{background:#dc2626}.dot.info{background:#2563eb}.title{font-weight:700}.msg{font-size:.8rem;color:#6b7280;line-height:1.5;margin-top:4px}.actions{display:flex;gap:7px;align-items:center}.open{color:#111827;text-decoration:none;border:1px solid #d1d5db;border-radius:8px;padding:8px 10px;font-size:.72rem;font-weight:700}.mark{background:none;border:0;color:#6b7280;text-decoration:underline;cursor:pointer;font:inherit;font-size:.7rem}.empty{background:#fff;border:1px dashed #d1d5db;border-radius:14px;padding:45px;text-align:center;color:#6b7280}@media(max-width:650px){.page{padding:20px 14px}.item{grid-template-columns:10px 1fr}.actions{grid-column:2;justify-content:flex-start}}</style></head><body><?php require_once '../common/navbar.php';?><div class="main-content"><main class="page"><div class="head"><div><h1>Notification Center</h1><div class="sub"><?=count($unread)?> unread operational alert(s). Alerts are calculated from current system records.</div></div><?php if($unread):?><form action="../process/markNotificationRead.php" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="all"><button class="btn">Mark all as read</button></form><?php endif;?></div><?php if($flash):?><div class="flash"><?=e($flash)?></div><?php endif;?><div class="list"><?php foreach($items as $item):?><article class="item <?=!empty($item['is_read'])?'read':''?>"><span class="dot <?=e($item['severity'])?>"></span><div><div class="title"><?=e($item['title'])?> <small>(<?=e($item['count'])?>)</small></div><div class="msg"><?=e($item['message'])?></div></div><div class="actions"><a class="open" href="<?=e($item['href'])?>">Open</a><?php if(empty($item['is_read'])):?><form action="../process/markNotificationRead.php" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="notification_key" value="<?=e($item['notification_key'])?>"><button class="mark">Mark read</button></form><?php endif;?></div></article><?php endforeach;?><?php if(!$items):?><div class="empty">No operational alerts were detected.</div><?php endif;?></div></main></div></body></html>
